-- AUTO-GENERATED from tennismaps.com regionid=104 (LA region) + curated booking metadata.
-- Source script: scripts/build_la_courts_seed.py

-- 1. Schema additions (idempotent) ----------------------------------------
alter table hotties.facilities
  add column if not exists tm_id int,
  add column if not exists category text,
  add column if not exists region text,
  add column if not exists phone text,
  add column if not exists website text,
  add column if not exists booking_provider text,
  add column if not exists online_booking boolean not null default false,
  add column if not exists facility_booking_url text;

create index if not exists facilities_category_idx on hotties.facilities (category);
create index if not exists facilities_region_idx on hotties.facilities (region);
create index if not exists facilities_online_booking_idx on hotties.facilities (online_booking);

-- 2. Sources --------------------------------------------------------------
on conflict (id) do update set
  name = excluded.name,
  booking_url = excluded.booking_url,
  scraper_type = excluded.scraper_type,
  notes = excluded.notes;

-- 3. Facilities ---------------------------------------------------------
-- Each row sourced from tennismaps.com. Lat/lng verified by tennismaps; addresses to geocode later.

on conflict (source_id, external_id) do update set
  name = excluded.name,
  lat = excluded.lat,
  lng = excluded.lng,
  num_courts = coalesce(excluded.num_courts, hotties.facilities.num_courts),
  category = excluded.category,
  region = excluded.region,
  phone = coalesce(excluded.phone, hotties.facilities.phone),
  online_booking = excluded.online_booking,
  facility_booking_url = excluded.facility_booking_url,
  tm_id = excluded.tm_id;

